package com.petlis.service.impl;
import org.junit.jupiter.api.Test;import java.sql.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class LegacyGroupingSessionTest {
 @Test void failedRestorationAbortsOnlyTheBorrowedConnection()throws Exception{Connection connection=mock(Connection.class);Statement query=mock(Statement.class);ResultSet result=mock(ResultSet.class);PreparedStatement set=mock(PreparedStatement.class);when(connection.createStatement()).thenReturn(query);when(query.executeQuery(anyString())).thenReturn(result);when(result.getString(1)).thenReturn("ONLY_FULL_GROUP_BY");when(connection.prepareStatement(anyString())).thenReturn(set);when(set.execute()).thenReturn(false).thenThrow(new SQLException("synthetic restore failure"));assertThrows(SQLException.class,()->LegacyGroupingSession.query(connection,()->"result"));verify(connection).abort(any());}
 @Test void originalModeIsRestoredOnSuccessAndFailure()throws Exception{for(boolean fail:new boolean[]{false,true}){Connection connection=mock(Connection.class);Statement query=mock(Statement.class);ResultSet result=mock(ResultSet.class);PreparedStatement set=mock(PreparedStatement.class);when(connection.createStatement()).thenReturn(query);when(query.executeQuery("SELECT @@SESSION.sql_mode")).thenReturn(result);when(result.getString(1)).thenReturn("STRICT_TRANS_TABLES,ONLY_FULL_GROUP_BY,NO_ZERO_DATE");when(connection.prepareStatement("SET SESSION sql_mode=?")).thenReturn(set);
  if(fail)assertThrows(SQLException.class,()->LegacyGroupingSession.query(connection,()->{throw new SQLException("synthetic query failure");}));else assertEquals("result",LegacyGroupingSession.query(connection,()->"result"));
  var order=inOrder(set);order.verify(set).setString(1,"STRICT_TRANS_TABLES,NO_ZERO_DATE");order.verify(set).execute();order.verify(set).close();order.verify(set).setString(1,"STRICT_TRANS_TABLES,ONLY_FULL_GROUP_BY,NO_ZERO_DATE");order.verify(set).execute();verify(connection,never()).abort(any());
 }}
}
